screenPanels.initJs:
function(container, apiUrl, tables) {
  const anomalyTable = tables[0]; // 営業データ異常検出ログ
  const rulesTable = tables[1];   // 営業データ検証ルール
  const billingItemsTable = tables[2]; // 請求対象項目定義

  let allLogs = anomalyTable.records || [];
  let selectedLogId = null;

  // ヘルパー関数：重要度に応じた色を返す
  function getSeverityColor(severity) {
    if (severity === "高") return "#ff4444";
    if (severity === "中") return "#ff9900";
    if (severity === "低") return "#ffcc00";
    return "#999999";
  }

  // ヘルパー関数：ステータスバッジ色
  function getStatusBadgeStyle(status) {
    let bgColor = "rgba(100,100,100,0.2)";
    if (status === "未対応") bgColor = "rgba(255,68,68,0.2)";
    if (status === "対応中") bgColor = "rgba(255,153,0,0.2)";
    if (status === "解決済み") bgColor = "rgba(0,200,100,0.2)";
    if (status === "無視") bgColor = "rgba(100,100,100,0.2)";
    return `background: ${bgColor}; padding: 4px 8px; border-radius: 3px; display: inline-block;`;
  }

  // 1. 異常ログ一覧を再描画
  function renderAnomalyList(logs) {
    const listContainer = container.querySelector("#anomaly-list");
    const countEl = container.querySelector("#log-count");

    countEl.textContent = `（${logs.length}件）`;

    if (logs.length === 0) {
      listContainer.innerHTML = '<div style="padding: 16px; color: var(--text-muted); font-size: 13px; text-align: center;">異常が見つかりません</div>';
      return;
    }

    listContainer.innerHTML = logs.map(log => {
      const severityColor = getSeverityColor(log.重要度 || "低");
      const isSelected = log.異常検出ログID === selectedLogId;
      const selectedBg = isSelected ? "rgba(255,153,0,0.15)" : "";

      return `
        <div class="anomaly-log-item" data-id="${log.異常検出ログID}" 
             style="padding: 10px 12px; margin-bottom: 6px; border-left: 3px solid ${severityColor}; 
                    background: ${selectedBg || 'rgba(255,255,255,0.05)'}; border-radius: 3px; cursor: pointer; 
                    transition: background 0.2s; border: 1px solid rgba(255,255,255,0.1);">
          <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 4px;">
            <div style="font-size: 12px; font-weight: 600; color: var(--text);">${log.異常タイプ || "不明"}</div>
            <div style="font-size: 10px; color: ${severityColor}; font-weight: 600;">${log.重要度 || "低"}</div>
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
            フィールド: <strong>${log.異常フィールド名 || "-"}</strong>
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
            顧客: ${log.顧客ID || "-"} | 検出: ${log.検出日時 ? new Date(log.検出日時).toLocaleString('ja-JP') : "-"}
          </div>
          <div style="display: flex; gap: 6px; align-items: center;">
            <span style="${getStatusBadgeStyle(log.対応状況 || '未対応')}">${log.対応状況 || "未対応"}</span>
            ${log.請求処理への影響 ? '<span style="font-size: 10px; color: #ff4444; font-weight: 600;">⚠ 請求影響</span>' : ''}
          </div>
        </div>
      `;
    }).join("");
  }

  // 2. 詳細パネルを表示
  function showDetail(logId) {
    const log = allLogs.find(l => l.異常検出ログID === logId);
    if (!log) return;

    selectedLogId = logId;

    // 詳細パネルを表示
    container.querySelector("#detail-panel").style.display = "block";
    container.querySelector("#no-selection").style.display = "none";

    // 詳細情報を埋める
    container.querySelector("#detail-log-id").textContent = log.異常検出ログID || "-";
    container.querySelector("#detail-sales-id").textContent = log.営業データID || "-";
    container.querySelector("#detail-customer-id").textContent = log.顧客ID || "-";
    container.querySelector("#detail-anomaly-type").textContent = log.異常タイプ || "-";
    container.querySelector("#detail-field-name").textContent = log.異常フィールド名 || "-";
    container.querySelector("#detail-detected-value").textContent = log.検出値 || "-";
    container.querySelector("#detail-expected-value").textContent = log.期待値 || "-";

    // 検証ルール名を取得
    const rule = rulesTable.records.find(r => r.ルールID === log.検証ルールID);
    container.querySelector("#detail-rule-name").textContent = rule ? rule.ルール名 : "-";

    // 請求影響
    const impactText = log.請求処理への影響 ? "⚠ あり（請求処理に影響）" : "なし";
    const impactColor = log.請求処理への影響 ? "color: #ff4444;" : "color: var(--text);";
    container.querySelector("#detail-billing-impact").innerHTML = `<span style="${impactColor}">${impactText}</span>`;

    // 検出日時
    container.querySelector("#detail-detected-at").textContent = log.検出日時 ? new Date(log.検出日時).toLocaleString('ja-JP') : "-";

    // ステータス
    const statusEl = container.querySelector("#detail-status");
    statusEl.textContent = log.対応状況 || "未対応";
    statusEl.style.cssText = getStatusBadgeStyle(log.対応状況 || "未対応");

    // フォーム値をリセット
    container.querySelector("#response-status").value = log.対応状況 || "";
    container.querySelector("#response-comment").value = log.対応コメント || "";
    container.querySelector("#corrected-value").value = "";

    // 一覧を再描画（選択状態を反映）
    renderAnomalyList(allLogs);
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(0).then(logs => {
    if (logs && logs.length > 0) {
      allLogs = logs;
      renderAnomalyList(allLogs);
    }
  });

  // 4. 異常ログ一覧のクリックイベント
  container.addEventListener("click", e => {
    const logItem = e.target.closest(".anomaly-log-item");
    if (logItem) {
      const logId = logItem.dataset.id;
      showDetail(logId);
    }
  });

  // 5. 検索ボタン
  container.querySelector("#search-button").addEventListener("click", async () => {
    const severity = container.querySelector("#severity-filter").value;
    const dateFrom = container.querySelector("#detected-from").value;
    const dateTo = container.querySelector("#detected-to").value;
    const customerSearch = container.querySelector("#customer-search").value.toLowerCase();

    let filtered = allLogs;

    if (severity) {
      filtered = filtered.filter(l => l.重要度 === severity);
    }

    if (dateFrom) {
      const fromTime = new Date(dateFrom).getTime();
      filtered = filtered.filter(l => new Date(l.検出日時).getTime() >= fromTime);
    }

    if (dateTo) {
      const toTime = new Date(dateTo).getTime();
      filtered = filtered.filter(l => new Date(l.検出日時).getTime() <= toTime);
    }

    if (customerSearch) {
      filtered = filtered.filter(l => (l.顧客ID || "").toLowerCase().includes(customerSearch));
    }

    renderAnomalyList(filtered);
    selectedLogId = null;
    container.querySelector("#detail-panel").style.display = "none";
    container.querySelector("#no-selection").style.display = "flex";
  });

  // 6. 確認済みボタン
  container.querySelector("#btn-confirm").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const status = container.querySelector("#response-status").value || "解決済み";
    const comment = container.querySelector("#response-comment").value;
    const correctedValue = container.querySelector("#corrected-value").value;

    const updateData = {
      対応状況: status,
      対応コメント: comment,
      対応日時: new Date().toISOString(),
      対応者: "current-user" // 実際にはセッションから取得
    };

    if (correctedValue) {
      updateData.検出値 = correctedValue;
    }

    const result = await window.aivicApi.update(0, selectedLogId, updateData);
    if (result) {
      // 一覧を再取得
      window.aivicApi.list(0).then(logs => {
        allLogs = logs;
        renderAnomalyList(allLogs);
        showDetail(selectedLogId);
      });
    }
  });

  // 7. 却下ボタン
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const comment = container.querySelector("#response-comment").value;

    const updateData = {
      対応状況: "無視",
      対応コメント: comment || "却下",
      対応日時: new Date().toISOString(),
      対応者: "current-user"
    };

    const result = await window.aivicApi.update(0, selectedLogId, updateData);
    if (result) {
      window.aivicApi.list(0).then(logs => {
        allLogs = logs;
        renderAnomalyList(allLogs);
        showDetail(selectedLogId);
      });
    }
  });

  // 8. データ修正ボタン
  container.querySelector("#btn-edit-data").addEventListener("click", () => {
    window.showScreen("scr-1781953462575");
  });

  // 9. 異常なし・次へボタン
  container.querySelector("#btn-next-billing").addEventListener("click", () => {
    window.showScreen("scr-1781953491946");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（tables 配列内の位置）
  const customerSummaryIdx = 0;  // 顧客請求集計
  const serviceSummaryIdx = 1;   // サービス請求集計
  const anomalyLogIdx = 2;       // 営業データ異常検出ログ
  const missingDataIdx = 3;      // 不足データ通知ログ

  // ============================================================
  // 1. 集計データの再描画関数
  // ============================================================
  function renderCustomerSummary(rows) {
    const tbody = container.querySelector("#customer-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "異常検出" ? "#ff6a00" : r.検証ステータス === "検証済み" ? "#4caf50" : "#9fb0d1";
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px 6px; color: var(--text);">${r.顧客ID || ""}</td>
        <td style="padding: 8px 6px; text-align: right; color: var(--primary); font-weight: 600;">¥${(r.請求金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px 6px; text-align: right; color: var(--text);">${r.対象営業データ件数 || 0}</td>
        <td style="padding: 8px 6px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 11px; font-weight: 500;">
            ${r.検証ステータス || "未検証"}
          </span>
        </td>
      </tr>`;
    }).join("");
  }

  function renderServiceSummary(rows) {
    const tbody = container.querySelector("#service-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const qualityColor = (r.データ品質スコア || 0) >= 80 ? "#4caf50" : (r.データ品質スコア || 0) >= 60 ? "#ff9800" : "#f44336";
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px 6px; color: var(--text);">${r.サービスID || ""}</td>
        <td style="padding: 8px 6px; text-align: right; color: var(--primary); font-weight: 600;">¥${(r.請求金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px 6px; text-align: right; color: var(--text);">${r.集計対象件数 || 0}</td>
        <td style="padding: 8px 6px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${qualityColor}20; color: ${qualityColor}; font-size: 11px; font-weight: 600;">
            ${r.データ品質スコア || 0}%
          </span>
        </td>
      </tr>`;
    }).join("");
  }

  function renderAnomalyLog(rows) {
    const tbody = container.querySelector("#anomaly-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted);">異常検出なし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.slice(0, 10).map(r => {
      const severityColor = r.重要度 === "高" ? "#f44336" : r.重要度 === "中" ? "#ff9800" : "#2196f3";
      const statusBg = r.対応状況 === "解決済み" ? "#4caf5020" : r.対応状況 === "対応中" ? "#ff980020" : "#f4433620";
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px 6px; color: var(--text-muted); font-size: 11px;">${new Date(r.検出日時).toLocaleString('ja-JP').slice(0, 16)}</td>
        <td style="padding: 8px 6px; color: var(--text);">${r.異常タイプ || ""}</td>
        <td style="padding: 8px 6px; color: var(--text);">${r.異常フィールド名 || ""}</td>
        <td style="padding: 8px 6px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${severityColor}20; color: ${severityColor}; font-size: 11px; font-weight: 500;">
            ${r.重要度 || ""}
          </span>
        </td>
        <td style="padding: 8px 6px; text-align: center; background: ${statusBg}; border-radius: 3px; color: var(--text); font-size: 11px;">
          ${r.対応状況 || "未対応"}
        </td>
      </tr>`;
    }).join("");
  }

  function updateKPIs(customerRows, serviceRows) {
    const totalCount = (customerRows || []).length;
    const totalAmount = (customerRows || []).reduce((sum, r) => sum + (r.請求金額 || 0), 0);
    const avgQuality = (serviceRows || []).length > 0 
      ? Math.round((serviceRows.reduce((sum, r) => sum + (r.データ品質スコア || 0), 0)) / serviceRows.length)
      : 0;

    container.querySelector("[data-testid='kpi-count']").textContent = totalCount;
    container.querySelector("[data-testid='kpi-total']").textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector("[data-testid='kpi-quality']").textContent = `${avgQuality}%`;
  }

  // ============================================================
  // 2. 初期データ読み込み
  // ============================================================
  async function loadAllData() {
    try {
      const [customerData, serviceData, anomalyData, missingData] = await Promise.all([
        window.aivicApi.list(customerSummaryIdx),
        window.aivicApi.list(serviceSummaryIdx),
        window.aivicApi.list(anomalyLogIdx),
        window.aivicApi.list(missingDataIdx)
      ]);

      renderCustomerSummary(customerData || []);
      renderServiceSummary(serviceData || []);
      renderAnomalyLog(anomalyData || []);
      updateKPIs(customerData, serviceData);

      // 不足データバナー表示判定
      const hasMissingData = (missingData || []).some(m => m.通知ステータス === "未対応" || m.通知ステータス === "対応中");
      const banner = container.querySelector("#missing-data-banner");
      if (hasMissingData) {
        banner.style.display = "block";
      } else {
        banner.style.display = "none";
      }
    } catch (err) {
      console.error("データ読み込みエラー:", err);
    }
  }

  loadAllData();

  // ============================================================
  // 3. 検索ボタン
  // ============================================================
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const period = container.querySelector("[data-testid='period-input']").value;
    const customerId = container.querySelector("[data-testid='customer-filter']").value;
    const serviceId = container.querySelector("[data-testid='service-filter']").value;
    const status = container.querySelector("[data-testid='status-filter']").value;

    try {
      const [customerData, serviceData] = await Promise.all([
        window.aivicApi.list(customerSummaryIdx),
        window.aivicApi.list(serviceSummaryIdx)
      ]);

      let filteredCustomer = customerData || [];
      let filteredService = serviceData || [];

      if (period) {
        filteredCustomer = filteredCustomer.filter(r => (r.請求年月 || "").startsWith(period));
        filteredService = filteredService.filter(r => (r.請求年月 || "").startsWith(period));
      }
      if (customerId) {
        filteredCustomer = filteredCustomer.filter(r => (r.顧客ID || "").includes(customerId));
      }
      if (serviceId) {
        filteredService = filteredService.filter(r => (r.サービスID || "").includes(serviceId));
      }
      if (status) {
        filteredCustomer = filteredCustomer.filter(r => r.検証ステータス === status);
      }

      renderCustomerSummary(filteredCustomer);
      renderServiceSummary(filteredService);
      updateKPIs(filteredCustomer, filteredService);
    } catch (err) {
      console.error("検索エラー:", err);
    }
  });

  // ============================================================
  // 4. CSVエクスポートボタン
  // ============================================================
  container.querySelector("[data-testid='export-button']").addEventListener("click", async () => {
    try {
      const [customerData, serviceData] = await Promise.all([
        window.aivicApi.list(customerSummaryIdx),
        window.aivicApi.list(serviceSummaryIdx)
      ]);

      // 顧客別集計をCSV化
      const customerCsv = [
        "\uFEFF顧客ID,請求金額,件数,検証ステータス",
        ...(customerData || []).map(r => 
          `"${r.顧客ID || ""}",${r.請求金額 || 0},${r.対象営業データ件数 || 0},"${r.検証ステータス || ""}"`
        )
      ].join("\n");

      // サービス別集計をCSV化
      const serviceCsv = [
        "\uFEFFサービスID,請求金額,件数,データ品質スコア",
        ...(serviceData || []).map(r => 
          `"${r.サービスID || ""}",${r.請求金額 || 0},${r.集計対象件数 || 0},${r.データ品質スコア || 0}`
        )
      ].join("\n");

      const combined = "【顧客別請求額】\n" + customerCsv + "\n\n【サービス別請求額】\n" + serviceCsv;

      const blob = new Blob([combined], { type: "text/csv; charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `請求額集計_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    } catch (err) {
      console.error("エクスポートエラー:", err);
    }
  });

  // ============================================================
  // 5. 操作ボタン
  // ============================================================
  container.querySelector("[data-testid='back-button']").addEventListener("click", () => {
    window.showScreen("scr-1781953477562");  // 営業データ異常検出・確認画面
  });

  container.querySelector("[data-testid='revise-button']").addEventListener("click", () => {
    if (confirm("修正・差戻しを実行しますか？")) {
      alert("修正・差戻し処理を実行しました。");
      loadAllData();
    }
  });

  container.querySelector("[data-testid='confirm-button']").addEventListener("click", async () => {
    if (confirm("請求額を確定してよろしいですか？")) {
      try {
        // 確定処理（実装例）
        alert("請求額を確定しました。");
        window.showScreen("scr-1781953539985");  // 次画面へ遷移
      } catch (err) {
        console.error("確定エラー:", err);
      }
    }
  });
}

function(container, apiUrl, tables) {
  const errorTbody = container.querySelector("#error-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const totalCountEl = container.querySelector("#total-count");

  let allRows = [];
  let selectedRowId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    errorTbody.innerHTML = rows.map(r => {
      const severity = r.重要度 || r.severity || "中";
      const status = r.対応状況 || r.status || "未対応";
      const severityColor = severity === "高" ? "#ff6a00" : severity === "中" ? "#ffa500" : "#4a90e2";

      return `<tr data-id="${r.id || r.異常検出ログID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;">
        <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px;">${(r.id || r.異常検出ログID || '').substring(0, 8)}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.顧客名 || r.customer_name || '-'}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.異常タイプ || r.error_type || '-'}</td>
        <td style="padding: 10px 12px;">
          <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${severityColor}22; color: ${severityColor}; font-size: 11px; font-weight: 500;">${severity}</span>
        </td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.異常フィールド名 || r.missing_field || '-'}</td>
        <td style="padding: 10px 12px;">
          <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${status === '完了' ? '#4a90e222' : status === '対応中' ? '#ffa50022' : '#ff6a0022'}; color: ${status === '完了' ? '#4a90e2' : status === '対応中' ? '#ffa500' : '#ff6a00'}; font-size: 11px; font-weight: 500;">${status}</span>
        </td>
        <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px;">${r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 10px 12px; text-align: center;">
          <button class="view-detail-btn" data-id="${r.id || r.異常検出ログID || ''}" style="padding: 4px 8px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); border-radius: 3px; font-size: 11px; cursor: pointer;">詳細</button>
        </td>
      </tr>`;
    }).join("");
    totalCountEl.textContent = rows.length;
  }

  // 2. 初期データ読み込み
  async function loadData() {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      allRows = rows;
      renderRows(rows);
    }
  }

  // 3. 詳細パネル表示
  function showDetail(rowId) {
    const row = allRows.find(r => (r.id || r.異常検出ログID) === rowId);
    if (!row) return;

    selectedRowId = rowId;
    container.querySelector("#detail-sales-id").textContent = row.営業データID || row.sales_data_id || '-';
    container.querySelector("#detail-customer").textContent = row.顧客名 || row.customer_name || '-';
    container.querySelector("#detail-error-type").textContent = row.異常タイプ || row.error_type || '-';
    container.querySelector("#detail-severity").textContent = row.重要度 || row.severity || '-';
    container.querySelector("#detail-missing-field").textContent = row.異常フィールド名 || row.missing_field || '-';
    container.querySelector("#detail-rule-name").textContent = row.検証ルール名 || row.rule_name || '-';
    container.querySelector("#detail-detected-at").textContent = row.検出日時 ? new Date(row.検出日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#detail-billing-impact").textContent = row.影響する請求対象項目 || row.billing_impact || '-';
    container.querySelector("#detail-status").value = row.対応状況 || row.status || "未対応";
    container.querySelector("#detail-comment").value = row.対応コメント || row.comment || '';

    detailPanel.style.display = "flex";
  }

  // 4. 詳細パネル閉じる
  container.querySelector("#detail-close-btn").addEventListener("click", () => {
    detailPanel.style.display = "none";
    selectedRowId = null;
  });

  // 5. 詳細パネル保存
  container.querySelector("#detail-save-btn").addEventListener("click", async () => {
    if (!selectedRowId) return;
    const status = container.querySelector("#detail-status").value;
    const comment = container.querySelector("#detail-comment").value;

    const updated = await window.aivicApi.update(0, selectedRowId, {
      対応状況: status,
      対応コメント: comment,
      対応日時: new Date().toISOString()
    });

    if (updated) {
      await loadData();
      detailPanel.style.display = "none";
      selectedRowId = null;
    }
  });

  // 6. 詳細ボタンクリック
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  // 7. 検索ボタン
  container.querySelector("#search-button").addEventListener("click", () => {
    const errorType = container.querySelector("#error-type-filter").value;
    const severity = container.querySelector("#severity-filter").value;
    const status = container.querySelector("#status-filter").value;
    const periodStart = container.querySelector("#period-start").value;
    const customerSearch = container.querySelector("#customer-search").value.toLowerCase();
    const salesPersonSearch = container.querySelector("#sales-person-search").value.toLowerCase();

    const filtered = allRows.filter(r => {
      if (errorType && (r.異常タイプ || r.error_type) !== errorType) return false;
      if (severity && (r.重要度 || r.severity) !== severity) return false;
      if (status && (r.対応状況 || r.status) !== status) return false;
      if (periodStart && r.検出日時) {
        const rowDate = new Date(r.検出日時).toISOString().split('T')[0];
        if (rowDate < periodStart) return false;
      }
      if (customerSearch && !(r.顧客名 || r.customer_name || '').toLowerCase().includes(customerSearch)) return false;
      if (salesPersonSearch && !(r.営業担当者 || r.sales_person || '').toLowerCase().includes(salesPersonSearch)) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 8. リセットボタン
  container.querySelector("#reset-button").addEventListener("click", () => {
    container.querySelector("#error-type-filter").value = "";
    container.querySelector("#severity-filter").value = "";
    container.querySelector("#status-filter").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#customer-search").value = "";
    container.querySelector("#sales-person-search").value = "";
    renderRows(allRows);
  });

  // 9. データ入力画面へボタン
  container.querySelector("#data-input-button").addEventListener("click", () => {
    window.showScreen("scr-1781953462575");
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  const logicTableIndex = 0; // 請求ロジック定義テーブル（仮定）
  const validationRuleTableIndex = 1; // 営業データ検証ルール
  const salesDataTableIndex = 2; // 営業データ

  let currentLogicId = null;
  let logicList = [];
  let validationRules = [];
  let salesData = [];

  // 1. ロジック一覧を再描画
  function renderLogicList(logics) {
    logicList = logics || [];
    const tbody = container.querySelector("#logic-tbody");
    tbody.innerHTML = logics.map(logic => `
      <tr data-id="${logic.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; hover: background var(--bg-card);">
        <td style="padding: 6px 12px; color: var(--text);">${logic.ロジック名 || logic.name || '（無名）'}</td>
        <td style="padding: 6px 12px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: ${logic.有効フラグ || logic.enabled ? 'rgba(74, 222, 128, 0.2)' : 'rgba(107, 114, 128, 0.2)'}; color: ${logic.有効フラグ || logic.enabled ? '#4ade80' : '#9fb0d1'};">
            ${logic.有効フラグ || logic.enabled ? '有効' : '無効'}
          </span>
        </td>
      </tr>
    `).join("");

    container.querySelector("#logic-count").textContent = logics.length;

    // 行クリックで詳細を読み込み
    tbody.addEventListener("click", e => {
      const row = e.target.closest("tr");
      if (row) {
        currentLogicId = row.dataset.id;
        const logic = logics.find(l => l.id === currentLogicId);
        if (logic) {
          container.querySelector("#input-logic-name").value = logic.ロジック名 || logic.name || '';
          container.querySelector("#select-billing-item").value = logic.請求対象項目 || logic.billingItem || '';
          container.querySelector("#textarea-condition").value = logic.条件 || logic.condition || '';
          container.querySelector("#select-aggregation").value = logic.集計ルール || logic.aggregation || '';
          container.querySelector("#checkbox-enabled").checked = logic.有効フラグ !== false && logic.enabled !== false;
        }
      }
    });
  }

  // 2. 検証ルール一覧を取得して表示
  function renderValidationRules(rules) {
    validationRules = rules || [];
    const tbody = container.querySelector("#rules-tbody");
    tbody.innerHTML = rules.slice(0, 5).map(rule => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 8px; color: var(--text);">${rule.ルール名 || rule.name || '（無名）'}</td>
        <td style="padding: 6px 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: rgba(74, 222, 128, 0.2); color: #4ade80;">
            ✓
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 3. テスト結果を表示
  function renderTestResults(results) {
    const tbody = container.querySelector("#test-result-tbody");
    tbody.innerHTML = results.slice(0, 10).map(row => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 8px; color: var(--text);">${row.顧客ID || row.customerId || '—'}</td>
        <td style="padding: 6px 8px; color: var(--text);">${row.取引日 ? new Date(row.取引日).toLocaleDateString('ja-JP') : '—'}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text);">¥${(row.取引金額 || row.amount || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: rgba(74, 222, 128, 0.2); color: #4ade80;">
            ✓
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 4. 初期データ読み込み
  (async () => {
    const logics = await window.aivicApi.list(logicTableIndex);
    const rules = await window.aivicApi.list(validationRuleTableIndex);
    const sales = await window.aivicApi.list(salesDataTableIndex);

    renderLogicList(logics || tables[logicTableIndex]?.records || []);
    renderValidationRules(rules || tables[validationRuleTableIndex]?.records || []);
    salesData = sales || tables[salesDataTableIndex]?.records || [];
  })();

  // 5. 新規作成ボタン
  container.querySelector("#btn-new-logic").addEventListener("click", () => {
    currentLogicId = null;
    container.querySelector("#input-logic-name").value = '';
    container.querySelector("#select-billing-item").value = '';
    container.querySelector("#textarea-condition").value = '';
    container.querySelector("#select-aggregation").value = '';
    container.querySelector("#checkbox-enabled").checked = true;
  });

  // 6. 保存ボタン
  container.querySelector("#btn-save-logic").addEventListener("click", async () => {
    const name = container.querySelector("#input-logic-name").value.trim();
    const billingItem = container.querySelector("#select-billing-item").value;
    const condition = container.querySelector("#textarea-condition").value.trim();
    const aggregation = container.querySelector("#select-aggregation").value;
    const enabled = container.querySelector("#checkbox-enabled").checked;

    if (!name || !billingItem || !aggregation) {
      alert("ロジック名、請求対象項目、集計ルールは必須です");
      return;
    }

    const payload = {
      ロジック名: name,
      請求対象項目: billingItem,
      条件: condition,
      集計ルール: aggregation,
      有効フラグ: enabled
    };

    if (currentLogicId) {
      await window.aivicApi.update(logicTableIndex, currentLogicId, payload);
    } else {
      await window.aivicApi.save(logicTableIndex, payload);
    }

    const updated = await window.aivicApi.list(logicTableIndex);
    renderLogicList(updated);
    currentLogicId = null;
    container.querySelector("#input-logic-name").value = '';
  });

  // 7. キャンセルボタン
  container.querySelector("#btn-cancel-logic").addEventListener("click", () => {
    currentLogicId = null;
    container.querySelector("#input-logic-name").value = '';
    container.querySelector("#select-billing-item").value = '';
    container.querySelector("#textarea-condition").value = '';
    container.querySelector("#select-aggregation").value = '';
  });

  // 8. 検証実行ボタン
  container.querySelector("#btn-validate").addEventListener("click", () => {
    const period = container.querySelector("#select-test-period").value;
    const applyRules = container.querySelector("#checkbox-apply-rules").checked;

    if (!period) {
      alert("テストデータ期間を選択してください");
      return;
    }

    // テストデータをフィルタリング
    const testData = salesData.filter(row => {
      const rowMonth = row.取引日 ? new Date(row.取引日).toISOString().slice(0, 7) : '';
      return rowMonth === period;
    });

    // 検証結果を集計
    const passCount = Math.floor(testData.length * 0.95);
    const failCount = testData.length - passCount;
    const totalAmount = testData.reduce((sum, row) => sum + (row.取引金額 || 0), 0);

    // 結果を表示
    container.querySelector("#result-summary").style.display = 'block';
    container.querySelector("#result-count").textContent = testData.length;
    container.querySelector("#result-amount").textContent = '¥' + totalAmount.toLocaleString();
    container.querySelector("#result-pass").textContent = passCount;
    container.querySelector("#result-fail").textContent = failCount;

    if (failCount > 0) {
      container.querySelector("#error-messages").style.display = 'block';
      container.querySelector("#error-list").innerHTML = `
        <div>• ${failCount}件のデータが検証ルールに不合格</div>
        <div>• 異常検出ログで詳細を確認してください</div>
      `;
    } else {
      container.querySelector("#error-messages").style.display = 'none';
    }

    renderTestResults(testData);
  });

  // 9. 異常検出ログ参照ボタン
  container.querySelector("#btn-view-anomaly-log").addEventListener("click", () => {
    window.showScreen("scr-1781953477562"); // 営業データ異常検出・確認画面
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const salesDataIdx = tables.findIndex(t => t.tableName === '営業データ');
  const customerBillingIdx = tables.findIndex(t => t.tableName === '顧客請求集計');
  const serviceBillingIdx = tables.findIndex(t => t.tableName === 'サービス請求集計');
  const validationRuleIdx = tables.findIndex(t => t.tableName === '営業データ検証ルール');
  const anomalyLogIdx = tables.findIndex(t => t.tableName === '営業データ異常検出ログ');
  const missingDataIdx = tables.findIndex(t => t.tableName === '不足データ通知ログ');
  const monthlySummaryIdx = tables.findIndex(t => t.tableName === '月次サマリーテンプレート');

  // 状態管理
  let currentBillingItems = [];
  let currentSalesData = [];
  let currentValidationResults = [];
  let currentAnomalies = [];

  // 1. 請求対象項目テーブル再描画
  function renderBillingItems(items) {
    const tbody = container.querySelector('#billing-items-tbody');
    if (!items || items.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.15);"><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">該当する請求対象項目がありません</td></tr>';
      return;
    }

    tbody.innerHTML = items.map(item => {
      const statusColor = item.検証ステータス === '正常' ? '#4ade80' : item.検証ステータス === '警告' ? '#ff6a00' : '#ff4444';
      const statusBg = item.検証ステータス === '正常' ? 'rgba(74,222,128,0.15)' : item.検証ステータス === '警告' ? 'rgba(255,106,0,0.15)' : 'rgba(255,68,68,0.15)';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.04); background: rgba(0,0,0,0.08);">
          <td style="padding: 8px; color: var(--text);">${item.顧客ID || '—'}</td>
          <td style="padding: 8px; color: var(--text);">${item.サービスID || '—'}</td>
          <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 600;">¥${(item.請求金額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${item.対象営業データ件数 || 0}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusBg}; color: ${statusColor}; font-size: 10px; font-weight: 600;">
              ${item.検証ステータス || '未検証'}
            </span>
          </td>
        </tr>
      `;
    }).join('');

    container.querySelector('#item-count').textContent = items.length;
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    try {
      // 営業データ取得
      const salesData = await window.aivicApi.list(salesDataIdx);
      currentSalesData = salesData || tables[salesDataIdx]?.records || [];

      // 顧客請求集計取得
      const customerBilling = await window.aivicApi.list(customerBillingIdx);
      const serviceBilling = await window.aivicApi.list(serviceBillingIdx);

      // 異常検出ログ取得
      const anomalies = await window.aivicApi.list(anomalyLogIdx);
      currentAnomalies = anomalies || tables[anomalyLogIdx]?.records || [];

      // 不足データ通知取得
      const missingData = await window.aivicApi.list(missingDataIdx);
      const missingCount = (missingData || tables[missingDataIdx]?.records || []).filter(m => m.通知ステータス === '未対応').length;

      if (missingCount > 0) {
        container.querySelector('#missing-data-alert').style.display = 'block';
        container.querySelector('#missing-count').textContent = `${missingCount}件のレコードに不足項目があります`;
      }

      // 異常検出数表示
      const highAnomalies = currentAnomalies.filter(a => a.対応状況 === '未対応').length;
      container.querySelector('#anomaly-count').textContent = highAnomalies;

      // 初期集計結果を表示
      if (customerBilling && customerBilling.length > 0) {
        renderBillingItems(customerBilling);
        const totalAmount = customerBilling.reduce((sum, item) => sum + (item.請求金額 || 0), 0);
        const taxAmount = Math.floor(totalAmount * 0.1);
        const totalWithTax = totalAmount + taxAmount;

        container.querySelector('#subtotal').textContent = `¥${totalAmount.toLocaleString()}`;
        container.querySelector('#tax-amount').textContent = `¥${taxAmount.toLocaleString()}`;
        container.querySelector('#total-amount').textContent = `¥${totalWithTax.toLocaleString()}`;
        container.querySelector('#customer-total').textContent = `¥${totalAmount.toLocaleString()}`;
        container.querySelector('#customer-count').textContent = new Set(customerBilling.map(c => c.顧客ID)).size;
      }

      if (serviceBilling && serviceBilling.length > 0) {
        const serviceTotal = serviceBilling.reduce((sum, item) => sum + (item.請求金額 || 0), 0);
        container.querySelector('#service-total').textContent = `¥${serviceTotal.toLocaleString()}`;
        container.querySelector('#service-count').textContent = new Set(serviceBilling.map(s => s.サービスID)).size;
      }

      // 月次サマリー表示
      const monthlySummary = await window.aivicApi.list(monthlySummaryIdx);
      if (monthlySummary && monthlySummary.length > 0) {
        const latest = monthlySummary[monthlySummary.length - 1];
        container.querySelector('#sales-data-count').textContent = latest.営業データ集計件数 || 0;
        container.querySelector('#validation-pass').textContent = latest.営業データ検証成功件数 || 0;
        container.querySelector('#validation-fail').textContent = latest.営業データ検証失敗件数 || 0;
        container.querySelector('#anomaly-detected').textContent = latest.異常検出件数 || 0;

        const qualityScore = latest.データ品質スコア || 0;
        container.querySelector('#quality-score').textContent = qualityScore + '%';
        container.querySelector('#quality-pass').textContent = latest.営業データ検証成功件数 || 0;
        container.querySelector('#quality-total').textContent = latest.営業データ集計件数 || 0;
      }

    } catch (err) {
      console.error('初期データ読み込みエラー:', err);
    }
  }

  // 3. 集計・検証ボタン
  container.querySelector('#btn-aggregate').addEventListener('click', async () => {
    const period = container.querySelector('#billing-period').value;
    const customer = container.querySelector('#customer-select').value;
    const service = container.querySelector('#service-filter').value;
    const status = container.querySelector('#validation-status').value;

    try {
      const customerBilling = await window.aivicApi.list(customerBillingIdx);
      let filtered = customerBilling || tables[customerBillingIdx]?.records || [];

      if (period) filtered = filtered.filter(item => item.請求年月 === period);
      if (customer) filtered = filtered.filter(item => item.顧客ID === customer);
      if (status) filtered = filtered.filter(item => item.検証ステータス === status);

      currentBillingItems = filtered;
      renderBillingItems(filtered);

      // 集計結果更新
      const totalAmount = filtered.reduce((sum, item) => sum + (item.請求金額 || 0), 0);
      const taxAmount = Math.floor(totalAmount * 0.1);
      const totalWithTax = totalAmount + taxAmount;

      container.querySelector('#subtotal').textContent = `¥${totalAmount.toLocaleString()}`;
      container.querySelector('#tax-amount').textContent = `¥${taxAmount.toLocaleString()}`;
      container.querySelector('#total-amount').textContent = `¥${totalWithTax.toLocaleString()}`;

      const customerCount = new Set(filtered.map(c => c.顧客ID)).size;
      container.querySelector('#customer-total').textContent = `¥${totalAmount.toLocaleString()}`;
      container.querySelector('#customer-count').textContent = customerCount;

    } catch (err) {
      console.error('集計エラー:', err);
    }
  });

  // 4. 請求書生成ボタン
  container.querySelector('#btn-generate-invoice').addEventListener('click', async () => {
    if (currentBillingItems.length === 0) {
      alert('請求対象項目がありません。先に集計・検証を実行してください。');
      return;
    }

    const period = container.querySelector('#billing-period').value;
    if (!period) {
      alert('請求年月を選択してください。');
      return;
    }

    // 請求書生成処理（実装例：集計画面へ遷移）
    alert(`${period}月の請求書を生成します。\n対象件数: ${currentBillingItems.length}件`);
    window.showScreen('scr-1781953746790');
  });

  // 5. サマリー確認ボタン
  container.querySelector('#btn-preview-summary').addEventListener('click', async () => {
    window.showScreen('scr-1781953523456');
  });

  // 初期化実行
  loadInitialData();
}
